185	\section{Distance measures}
186	
187	\begin{definition}[Distance between states]\label{def:state-distance}
188		Let $\{\ket{\psi_n}\}_{n \in \N}$ and $\{\ket{\psi'_n}\}_{n \in \N}$ be two families of states in the same space $\mathcal H$. For a function $\delta \colon \N \to [0,1]$ we say that $\{\ket{\psi_n}\}$ and $\{\ket{\psi'_n}\}$ are \emph{$\delta$-close}, denoted $\ket{\psi} \approx_\delta \ket{\psi'}$, if
189		\[
190			\lVert \ket{\psi_n} - \ket{\psi'_n} \rVert^2 = O(\delta(n))\,.
191		\]
192		The dependence of the states and of $\delta$ on the indexing parameter $n$ is generally left implicit; we write, e.g., $\ket{\psi}$ for $\ket{\psi_n}$.
193	\end{definition}
194	
195	\begin{definition}[Consistency between POVMs]\label{def:consistency}
196		\lean{MIPStarRE.QPBT.consistencyDefect, MIPStarRE.QPBT.IsConsistentWithin}
197		\leanok
198		\uses{def:povm-conventions, def:state-distance}
199		Let $\mathcal X$ be a finite set and $\mu$ a distribution on $\mathcal X$. Let $\ket{\psi} \in \mathcal H_A \ot \mathcal H_B$ be a quantum state, and for all $x \in \mathcal X$ let $\{A^x_a\}$ and $\{B^x_a\}$ be POVMs. We write
200		\[
201			A^x_a \ot \Id_B \simeq_\delta \Id_A \ot B^x_a
202		\]
203		on state $\ket{\psi}$ and distribution $\mu$ if
204		\[
205			\E_{x \sim \mu} \sum_{a \ne b} \bra{\psi} A^x_a \ot B^x_b \ket{\psi} = O(\delta)\,.
206		\]
207		In this case we say that $\{A^x_a\}$ and $\{B^x_a\}$ are \emph{$\delta$-consistent} on $\ket{\psi}$. As in Definition~\ref{def:state-distance}, the $O(\cdot)$ refers to families of POVMs and states indexed by an implicit parameter $n \in \N$, and is taken as $n \to \infty$.
208	\end{definition}
209	
210	A measurement that is consistent on $\ket{\psi}$ in the sense of Definition~\ref{def:consistent-measurement} is $0$-consistent with itself on the same state under the singleton distribution, and vice versa: if $\sum_a \bra{\psi} M_a \ot M_a \ket{\psi} = 1$, then $M_a \ot \Id\, \ket{\psi} = \Id \ot M_a\, \ket{\psi}$ for every $a$, by the equality case of the Cauchy--Schwarz inequality applied outcome by outcome.
211	
212	% The source (references/qpbt-paper/06_nonlocal_games_and_mipstar.tex:257-274) states this
213	% definition for pairs of POVMs but applies the relation to arbitrary operator families:
214	% to plain operators at 06:313-330, to sets of matrices at 06:364-380, and to products and
215	% commutators, compared against the zero family, at 06:409-445. The general form below,
216	% for arbitrary finite families of operators, is the one of the NEEXP source
217	% (references/neexp-paper/05_quantum_preliminaries.tex:385-391), from which the distance
218	% calculus is imported; the POVM case is singled out after the display.
219	\begin{definition}[State-dependent distance between operator families]\label{def:povm-distance}
220		\uses{def:povm-conventions, def:state-distance}
221		Let $\mathcal X$ and $\mathcal A$ be finite sets and $\mu$ a distribution on $\mathcal X$. Let $\ket{\psi} \in \mathcal H$ be a quantum state, and for all $x \in \mathcal X$ let $\{M^x_a\}_{a \in \mathcal A}$ and $\{N^x_a\}_{a \in \mathcal A}$ be two families of linear operators on $\mathcal H$. We say that \emph{$\{M^x_a\}$ and $\{N^x_a\}$ are $\delta$-close on state $\ket{\psi}$ and under distribution $\mu$} if
222		\[
223			\E_{x \sim \mu} \sum_a \lVert (M^x_a - N^x_a)\, \ket{\psi} \rVert^2 \le O(\delta)\,,
224		\]
225		and we write $M^x_a \approx_\delta N^x_a$ to denote this when the state $\ket{\psi}$ and the distribution $\mu$ are clear from context. This distance is referred to as the \emph{state-dependent} distance. The principal case is that in which $\{M^x_a\}$ and $\{N^x_a\}$ are POVMs on $\mathcal H$, and we then speak of the state-dependent distance between the POVMs; but the relation is used for arbitrary operator families --- for instance for products of measurement operators, or for commutators compared against the identically zero family, as in Lemma~\ref{lem:commutation-analysis} below.
226	\end{definition}
227	
228	\begin{definition}[Distance between strategies]\label{def:strategy-distance}
229		\lean{MIPStarRE.QPBT.AreCloseStrategies}
230		\leanok
231		\uses{def:tensor-product-strategy, def:state-distance, def:povm-distance}
232		Let $\mathfrak G = (\mathcal X, \mathcal Y, \mathcal A, \mathcal B, \mu, D)$ be a nonlocal game and let $\mathcal S = (\psi, A, B)$ and $\mathcal S' = (\psi', A', B')$ be strategies for $\mathfrak G$. For $\delta \in [0,1]$ we say that \emph{$\mathcal S$ is $\delta$-close to $\mathcal S'$} if the following conditions hold.
233		\begin{enumerate}
234			\item The states $\ket{\psi}, \ket{\psi'}$ are states in the same Hilbert space $\mathcal H_A \ot \mathcal H_B$ and are $\delta$-close.
235			\item For all $x \in \mathcal X$ and $y \in \mathcal Y$, we have $A^x_a \approx_\delta (A')^x_a$ and $B^y_b \approx_\delta (B')^y_b$, with the approximations holding under the distribution $\mu$ (i.e.\ under its corresponding marginals), on either $\ket{\psi}$ or $\ket{\psi'}$.
236		\end{enumerate}
237	\end{definition}
238	
239	\begin{remark}[Asymptotic reading of the distance relations]\label{rem:asymptotic-distance}
240		Definitions~\ref{def:state-distance}, \ref{def:consistency}, and \ref{def:povm-distance} are asymptotic: every $\approx_\delta$ and $\simeq_\delta$ statement refers to families of states and measurement families indexed by an implicit parameter $n \in \N$, and the $O(\cdot)$ is taken as $n \to \infty$. None of these relations is a pointwise inequality with an explicit constant. By contrast, the corresponding relations used in the low individual degree chapters (Definitions~\ref{def:simeq} and~\ref{def:approx_delta}) carry no hidden constant. Any explicit quantitative version of the present relations therefore retains the constants absorbed into the $O(\cdot)$; for instance, the triangle inequality of Lemma~\ref{fact:triangle} carries a factor $2$ inside the $O(\cdot)$.
241	\end{remark}
242	
243	We record several useful facts about the consistency measure and the state-dependent distance. For the statements imported without proof, readers are referred to Sections~4.4 and~4.5 of \cite{Natarajan2018NEEXP}.
244	
245	\begin{lemma}[Consistency versus closeness; Facts 4.13 and 4.14 in \cite{Natarajan2018NEEXP}]\label{fact:agreement}
246		\lean{MIPStarRE.QPBT.opFamilyDistSq_le_two_mul_consistencyDefect, MIPStarRE.QPBT.consistencyDefect_le_opFamilyDistSq_of_projective, MIPStarRE.QPBT.consistencyDefect_le_sqrt_of_projective_left}
247		\uses{def:consistency, def:povm-distance}
248		For POVMs $\{A^x_a\}$ and $\{B^x_a\}$, the following hold.
249		\begin{enumerate}
250			\item If $A^x_a \ot \Id_B \simeq_\delta \Id_A \ot B^x_a$, then $A^x_a \ot \Id_B \approx_\delta \Id_A \ot B^x_a$.
251			\item If $A^x_a \ot \Id_B \approx_\delta \Id_A \ot B^x_a$ \emph{and} $\{A^x_a\}$ and $\{B^x_a\}$ are projective measurements, then $A^x_a \ot \Id_B \simeq_\delta \Id_A \ot B^x_a$.
252			\item If $A^x_a \ot \Id_B \approx_\delta \Id_A \ot B^x_a$ and either $\{A^x_a\}$ or $\{B^x_a\}$ is a projective measurement, then $A^x_a \ot \Id_B \simeq_{\delta^{1/2}} \Id_A \ot B^x_a$.
253		\end{enumerate}
254	\end{lemma}
255	\begin{proof}
256		\uses{lem:distance-consistency-term,
257			lem:distance-point-distance-le-defect,
258			lem:distance-projective-point-distance, lem:distance-nonnegative,
259			lem:distance-projective-left-square-root}
260		Stated in the source without proof; these are Facts 4.13 and 4.14 of \cite{Natarajan2018NEEXP}. For the first item, expand each term $\lVert (A^x_a \ot \Id - \Id \ot B^x_a)\ket{\psi} \rVert^2$ and use $ (A^x_a)^2 \le A^x_a$, $(B^x_a)^2 \le B^x_a$ together with completeness of the two POVMs: summing over $a$ and averaging over $x$ bounds the total by at most twice the off-diagonal mass, which is $O(\delta)$ by hypothesis. When both families are projective the two operator inequalities hold with equality, so the expansion equals exactly twice the off-diagonal mass; reading this identity in the other direction gives the second item. For the third item, write the off-diagonal mass $\sum_{a \ne b} \bra{\psi} A^x_a \ot B^x_b \ket{\psi}$ as an inner product involving $(A^x_a \ot \Id - \Id \ot B^x_a)\ket{\psi}$, using projectivity of one of the two families, and apply the Cauchy--Schwarz inequality; this route costs a square root in the error.
261	\end{proof}
262	
263	\begin{lemma}[Fact 4.20 in \cite{Natarajan2018NEEXP}]\label{fact:add-a-proj}
264		\lean{MIPStarRE.QPBT.opFamilyDistSq_mul_left_le}
265		\leanok
266		\uses{def:povm-distance}
267		Let $\mathcal A, \mathcal B, \mathcal C$ be finite sets, and let $\mu$ be a distribution over question pairs $(x,y)$. Let $\{A^x_{a,\,b}\}$ and $\{B^x_{a,\,b}\}$ be operators whose outcomes range over the product set $\mathcal A \times \mathcal B$. Suppose a set of operators $\{C^y_{a,\,c}\}$, whose outcomes range over the product set $\mathcal A \times \mathcal C$, satisfies the condition $\sum_c (C^y_{a,\,c})^\dagger C^y_{a,\,c} \le \Id$ for all $a$ and all $y$. If $A^x_{a,\,b} \approx_\delta B^x_{a,\,b}$ on average over $x$ sampled from the corresponding marginal of the distribution $\mu$, then $C^y_{a,\,c} A^x_{a,\,b} \approx_\delta C^y_{a,\,c} B^x_{a,\,b}$ on average over $(x,y)$ sampled from $\mu$.
268	\end{lemma}
269	\begin{proof}
270		\leanok
271		\uses{lem:distance-sum-contraction}
272		Fix questions $x, y$ and answers $a \in \mathcal A$, $b \in \mathcal B$. Then
273		\begin{align*}
274			\sum_c \bigl\lVert (C^y_{a,\,c} A^x_{a,\,b} - C^y_{a,\,c} B^x_{a,\,b})\, \ket{\psi} \bigr\rVert^2
275			&= \bra{\psi} (A^x_{a,\,b} - B^x_{a,\,b})^\dagger \Bigl( \sum_c (C^y_{a,\,c})^\dagger C^y_{a,\,c} \Bigr) (A^x_{a,\,b} - B^x_{a,\,b}) \ket{\psi}\\
276			&\le \bigl\lVert (A^x_{a,\,b} - B^x_{a,\,b})\, \ket{\psi} \bigr\rVert^2\,,
277		\end{align*}
278		where the inequality uses the assumption $\sum_c (C^y_{a,\,c})^\dagger C^y_{a,\,c} \le \Id$. Summing over $a, b$ and averaging over $(x,y) \sim \mu$ yields the conclusion.
279	\end{proof}
